@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/*
 * Folio — dark "folder" skeuomorphism.
 *
 * Built from a single reference: a 3D folding-card / manila-folder surface.
 * The material language:
 *   - Deep charcoal -> black folder body (radial dome, lit from above)
 *   - A CRISP bright top-edge rim highlight where light catches the fold,
 *     plus faint vertical rim highlights on the left/right edges (the folded
 *     side walls). This 4-sided inset rim is Folio's signature, distinct from
 *     a single soft top highlight.
 *   - Very soft, deep, far-throwing ambient shadow (the folder floats over
 *     the page and casts a wide blurred contact pool).
 *   - One warm signature hue: paper amber, the only colour in an otherwise
 *     monochrome charcoal/paper palette.
 *
 * Per repo rule every colour is oklch(), including inside shadow stacks.
 */

:root {
  /* ─── Surfaces: elevation = lighter charcoal (the folder body catches light) ─── */
  --background: oklch(0.13 0.004 70);        /* deepest plane, faint warm black */
  --foreground: oklch(0.96 0.006 80);        /* warm paper white */

  --card: oklch(0.175 0.004 70);             /* raised folder surface */
  --card-foreground: oklch(0.96 0.006 80);

  --popover: oklch(0.205 0.004 70);          /* floating surface */
  --popover-foreground: oklch(0.96 0.006 80);

  /* ─── Primary: warm paper amber (the lone hue) ─── */
  --primary: oklch(0.81 0.115 78);
  --primary-foreground: oklch(0.22 0.035 72);

  --secondary: oklch(0.225 0.004 70);
  --secondary-foreground: oklch(0.9 0.005 80);

  --muted: oklch(0.2 0.003 70);
  --muted-foreground: oklch(0.63 0.006 75);

  --accent: oklch(0.255 0.012 78);           /* warm-tinted hover surface */
  --accent-foreground: oklch(0.96 0.006 80);

  --destructive: oklch(0.62 0.21 25);
  --destructive-foreground: oklch(0.97 0 0);

  --border: oklch(1 0 0 / 0.09);
  --input: oklch(1 0 0 / 0.05);
  --ring: oklch(0.81 0.115 78);
  --radius: 0.75rem;                          /* 0.75rem: rounder than default, matches the folder's rounded-xl cards */

  /*
   * ─── Shadow scale ───
   * Each tier stacks Folio's 4-sided rim (top bright + side faint) over a
   * sharp contact shadow and a wide soft ambient pool. Higher tiers brighten
   * the rim and throw the ambient farther (-0.75rem spread, big blur) to read as
   * "lifted off the page" like the reference folder cover.
   */
  --shadow-xs:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.07),
    0 0.0625rem 0.0625rem oklch(0 0 0 / 0.4),
    0 0.0625rem 0.1875rem -0.0625rem oklch(0 0 0 / 0.35);

  --shadow-sm:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.1),
    inset 0.0625rem 0 0 oklch(1 0 0 / 0.04),
    inset -0.0625rem 0 0 oklch(1 0 0 / 0.04),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.5),
    0 0.25rem 0.75rem -0.125rem oklch(0 0 0 / 0.45);

  --shadow-md:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.14),
    inset 0.0625rem 0 0 oklch(1 0 0 / 0.05),
    inset -0.0625rem 0 0 oklch(1 0 0 / 0.05),
    0 0.125rem 0.25rem oklch(0 0 0 / 0.55),
    0 0.625rem 1.5rem -0.25rem oklch(0 0 0 / 0.5);

  --shadow-lg:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.16),
    inset 0.0625rem 0 0 oklch(1 0 0 / 0.06),
    inset -0.0625rem 0 0 oklch(1 0 0 / 0.06),
    0 1rem 2.5rem -0.5rem oklch(0 0 0 / 0.65),
    0 1.5625rem 3.125rem -0.75rem oklch(0 0 0 / 0.55);

  --shadow-xl:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.2),
    inset 0.0625rem 0 0 oklch(1 0 0 / 0.07),
    inset -0.0625rem 0 0 oklch(1 0 0 / 0.07),
    0 1.5rem 3.5rem -0.625rem oklch(0 0 0 / 0.7),
    0 2.5rem 5rem -1.25rem oklch(0 0 0 / 0.6);

  /* Aliases used directly by component class strings ([box-shadow:var(--shadow-s)] etc). */
  --shadow-s: var(--shadow-sm);
  --shadow-m: var(--shadow-md);
  --shadow-l: var(--shadow-lg);

  /* Inset/pressed — inputs sit BELOW the folder surface (recessed pocket). */
  --shadow-inset:
    inset 0 0.0625rem 0.1875rem oklch(0 0 0 / 0.5),
    inset 0 -0.0625rem 0 oklch(1 0 0 / 0.04);

  /* Default raised control (folder tab). */
  --shadow-button:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.16),
    inset 0.0625rem 0 0 oklch(1 0 0 / 0.05),
    inset -0.0625rem 0 0 oklch(1 0 0 / 0.05),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.5),
    0 0.25rem 0.625rem -0.125rem oklch(0 0 0 / 0.45);

  --shadow-button-hover:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.2),
    inset 0.0625rem 0 0 oklch(1 0 0 / 0.07),
    inset -0.0625rem 0 0 oklch(1 0 0 / 0.07),
    0 0.125rem 0.25rem oklch(0 0 0 / 0.55),
    0 0.5rem 1.125rem -0.1875rem oklch(0 0 0 / 0.5);

  /* Amber paper tab — primary fill. Same rim recipe, warmed glow instead of black ambient. */
  --shadow-primary:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.3),
    0 0 0 0.0625rem oklch(0.81 0.115 78 / 0.25),
    0 0.0625rem 0.1875rem oklch(0 0 0 / 0.5),
    0 0.375rem 1rem -0.125rem oklch(0.75 0.13 75 / 0.28);

  /* The folder body radial dome + paper sheet gradients, reused by surfaces. */
  --folio-dome: radial-gradient(circle at 50% 0%, oklch(0.24 0.005 70) 0%, oklch(0.175 0.004 70) 55%, oklch(0.12 0.003 70) 100%);
  --folio-paper: linear-gradient(oklch(0.99 0.003 85) 0%, oklch(0.95 0.004 85) 100%);

  /* Fractal-noise grain, the reference's signature surface texture. */
  --folio-noise: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");

  /* ─── Chart palette: warm amber ramp (one hue, five shades). ─── */
  --chart-1: var(--primary);
  --chart-2: oklch(from var(--primary) calc(l - 0.09) calc(c * 0.92) h);
  --chart-3: oklch(from var(--primary) calc(l - 0.18) calc(c * 0.84) h);
  --chart-4: oklch(from var(--primary) calc(l - 0.27) calc(c * 0.76) h);
  --chart-5: oklch(from var(--primary) calc(l - 0.36) calc(c * 0.68) h);

  /* --- Motion (standard profile) ---
     Bare transition-* and ease-* classes read these; durations are
     duration-fast, duration-base and duration-slow once installed. */
  --transition-duration-fast: 150ms;
  --transition-duration-base: 200ms;
  --transition-duration-slow: 280ms;
  --ease-out: cubic-bezier(0.165, 0.84, 0.44, 1);
  --ease-in-out: cubic-bezier(0.645, 0.045, 0.355, 1);
  --ease-in: cubic-bezier(0.55, 0.055, 0.675, 0.19);
  --default-transition-duration: var(--transition-duration-fast);
  --default-transition-timing-function: var(--ease-out);

  /* AI parts: the label that marks what a model wrote. */
  --ai-label: var(--muted);
  --ai-label-foreground: var(--foreground);
}

/* Registers duration-fast, duration-base and duration-slow, which the
   components use. `reference` writes no variable that points at itself. */
@theme inline reference {
  --transition-duration-fast: var(--transition-duration-fast);
  --transition-duration-base: var(--transition-duration-base);
  --transition-duration-slow: var(--transition-duration-slow);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 0.25rem);
  --radius-md: calc(var(--radius) - 0.125rem);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 0.375rem);

  --shadow-s: var(--shadow-s);
  --shadow-m: var(--shadow-m);
  --shadow-l: var(--shadow-l);
  --shadow-inset: var(--shadow-inset);
  --shadow-button: var(--shadow-button);
  --shadow-button-hover: var(--shadow-button-hover);
  --shadow-primary: var(--shadow-primary);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }

  ::selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }
  /* stylelint-disable-next-line selector-no-vendor-prefix */
  ::-moz-selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }

  textarea {
    resize: vertical;
  }
  @supports (field-sizing: content) {
    textarea {
      field-sizing: content;
      max-height: 20lh;
      overflow-y: auto;
    }
  }

  /* Reserve the scrollbar gutter so the page keeps its width whenever the
     scrollbar comes and goes: content loading in, moving between a short
     and a tall page, or a scroll lock that just hides overflow. */
  html {
    scrollbar-gutter: stable;
  }
  @supports (scrollbar-gutter: stable) {
    html body[data-scroll-locked] {
      /* Radix's scroll lock re-adds the scrollbar width as body margin. The
         stable gutter already reserves it, so without this the two stack and
         opening a dialog shifts the page the other way. */
      margin-right: 0 !important;
    }
  }
}

@layer utilities {
  /* Show an invalid field on the field itself, not only in the message under
     it. Declared after Tailwind's utilities, so it wins over the field's own
     border and focus-ring classes. */
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
  [role="radiogroup"][aria-invalid="true"] [role="radio"] {
    border-color: var(--destructive);
  }
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]):focus-visible,
  [role="radiogroup"][aria-invalid="true"] [role="radio"]:focus-visible {
    border-color: var(--destructive);
    --tw-ring-color: color-mix(in oklch, var(--destructive) 35%, transparent);
  }

  /* Shake a field once when it turns invalid. */
  @keyframes deny-shake {
    25% { translate: -0.09375rem; }
    50% { translate: 0.109375rem; }
    75% { translate: -0.109375rem; }
  }
  @media (prefers-reduced-motion: no-preference) {
    [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
    [role="radiogroup"][aria-invalid="true"] [role="radio"],
    [data-input-otp-container]:has([aria-invalid="true"]) {
      animation: deny-shake 250ms linear;
    }
  }
}

:root {
  --layout-density: comfortable;
  --layout-density-source: design-system;
  --layout-sidebar: calc(var(--spacing, 0.25rem) * 56);
  --layout-inset: calc(var(--spacing, 0.25rem) * 6);
  --layout-section-gap: calc(var(--spacing, 0.25rem) * 8);
  --layout-column-gap: calc(var(--spacing, 0.25rem) * 4);
  --layout-card-padding: calc(var(--spacing, 0.25rem) * 5);
}

